(()=>{'use strict';
const modes=['adaptive','hires','lossless','saver'];let mode='adaptive',endpoint='';try{mode=localStorage.getItem('oktawka-stream-quality')||mode;endpoint=localStorage.getItem('oktawka-hifi')||''}catch{}if(!modes.includes(mode))mode='adaptive';
const norm=s=>String(s||'').normalize('NFKC').toLowerCase().replace(/[^\p{L}\p{N}]/gu,'');
function safeURL(value){const u=new URL(value);if(u.protocol!=='https:'||u.username||u.password)throw Error('Use an HTTPS endpoint without credentials in its URL.');return u}
function qualities(){const c=navigator.connection;return mode==='hires'?['HI_RES_LOSSLESS','LOSSLESS']:mode==='saver'?['HIGH','LOW']:mode==='lossless'?['LOSSLESS']:c&&(c.saveData||/2g/.test(c.effectiveType)||c.downlink>0&&c.downlink<1.5)?['HIGH','LOW']:['LOSSLESS','HIGH']}
function status(text){if(window.OktawkaStreaming)window.OktawkaStreaming.pending=text;for(const id of ['quality','np-quality','stream-status']){const el=document.getElementById(id);if(el){el.textContent=text||(tracks[current]?window.MonoAudioQuality.label(tracks[current]):'Quality unverified');if(text)el.hidden=false}}}
function failure(message,terminal=false){return Object.assign(new Error(message),{terminal})}
function queueURL(value,base,id){const u=new URL(value,base);const root=new URL(base);if(u.origin!==root.origin||u.search||u.hash||u.username||u.password||!u.pathname.endsWith('/playback/requests/'+encodeURIComponent(id)))throw failure('The service returned an invalid queue address.',true);return u}
function wait(ms,signal){return new Promise((resolve,reject)=>{let timer;const stop=()=>{clearTimeout(timer);signal?.removeEventListener('abort',stop);reject(new DOMException('Cancelled','AbortError'))};if(signal?.aborted)return stop();timer=setTimeout(()=>{signal?.removeEventListener('abort',stop);resolve()},ms);signal?.addEventListener('abort',stop,{once:true})})}
async function request(url,signal,method='GET'){const c=new AbortController(),abort=()=>c.abort();signal?.addEventListener('abort',abort,{once:true});if(signal?.aborted)abort();const timer=setTimeout(abort,12000);try{const r=await fetch(url,{method,signal:c.signal,credentials:'omit',referrerPolicy:'no-referrer',redirect:'error'});if(!r.ok)throw failure(r.status===401||r.status===403?'HiFi account access failed. Check the service’s Tidal login.':r.status===429?'HiFi is rate limited. Wait before retrying.':'HiFi service returned '+r.status+'. Retry later.',[401,403,429].includes(r.status));if(method==='DELETE')return {};return {response:r,data:await r.json()}}catch(e){if(signal?.aborted)throw new DOMException('Cancelled','AbortError');if(e.name==='AbortError')throw failure('HiFi did not respond in time.',true);throw e}finally{clearTimeout(timer);signal?.removeEventListener('abort',abort)}}
async function get(path,params,signal,base=endpoint){const u=safeURL(base.replace(/\/$/,'')+'/'+(path?path+'/':''));u.search=new URLSearchParams(params);let result=await request(u,signal),cancelURL=null,complete=false;try{for(let attempt=0;result.response.status===202;attempt++){const d=result.data;if(!/^[a-zA-Z0-9_-]{1,128}$/.test(d.requestId||''))throw failure('Invalid HiFi queue response.',true);const poll=queueURL(d.statusUrl,u,d.requestId);cancelURL=queueURL(d.cancelUrl,u,d.requestId);if(attempt>=20)throw failure('HiFi queue timed out. Your request has been cancelled; retry shortly.',true);status('Waiting for HiFi'+(Number.isFinite(d.queuePosition)?' · position '+d.queuePosition:''));const seconds=Number(result.response.headers?.get('Retry-After'));await wait(Math.max(1000,Math.min(3000,seconds>0?seconds*1000:2000)),signal);result=await request(poll,signal)}if(['failed','cancelled','canceled'].includes(result.data?.status))throw failure('HiFi could not prepare this track. Retry shortly.',true);complete=true;return result.data}finally{if(cancelURL&&!complete)try{await request(cancelURL,null,'DELETE')}catch{}}}

function match(t,track){return norm(t.title)===norm(track.title)&&norm(t.artist?.name||t.artists?.[0]?.name)===norm(track.artist)&&(!track.album||norm(t.album?.title)===norm(track.album))&&(!track.duration||Math.abs(Number(t.duration)-Number(track.duration))<=3)&&!t.version&&t.allowStreaming!==false}
function manifest(d,id,quality){if(String(d.trackId)!==String(id)||d.assetPresentation!=='FULL'||d.manifestMimeType!=='application/vnd.tidal.bts')throw Error('This service did not return a supported full-track audio file.');const m=JSON.parse(atob(d.manifest));if(m.encryptionType!=='NONE'||m.urls?.length!==1)throw Error('This stream needs a playback format that Oktawka does not yet support.');const lossless=/flac/i.test(m.codecs||'')&&m.mimeType==='audio/flac';if(['LOSSLESS','HI_RES_LOSSLESS'].includes(quality)&&!lossless)throw Error('The service did not return lossless audio.');if(!lossless&&!/^audio\/(mp4|aac|mpeg)$/.test(m.mimeType))throw Error('Unsupported audio codec.');return {url:safeURL(m.urls[0]).href,sourceCodec:lossless?'FLAC':'AAC',lossyFallback:!lossless,lossless:false,format:lossless?'FLAC · bit depth unverified':'Lossy AAC',provider:'HiFi',reportedQuality:{bitDepth:d.bitDepth,sampleRate:d.sampleRate}}}
async function resolve(track,signal){if(!endpoint)return null;const base=endpoint;status('Searching '+(mode==='saver'?'data-saving':'lossless')+' audio · '+track.title);const result=await get('search',{s:track.artist+' '+track.title,limit:'25'},signal,base);const rows=result.data?.items||[];const found=rows.find(t=>match(t,track));if(!found)throw Error('No exact artist, album and song match on your HiFi service.');let error;const requestedMode=mode,choices=qualities();for(const q of choices){if(signal.aborted)throw new DOMException('Cancelled','AbortError');status('Loading '+(q==='HI_RES_LOSSLESS'?'hi-res FLAC':q==='LOSSLESS'?'lossless FLAC':'lossy AAC')+' · '+track.title);try{return {...track,...manifest((await get('track',{id:found.id,quality:q},signal,base)).data,found.id,q),catalogId:track.id,requestedMode,requestedQuality:q,qualityFallback:q!==choices[0]}}catch(e){if(signal.aborted||e.terminal)throw e;error=e}}throw error}
function settings(){modal(`<div class="eyebrow">STREAMING · NO DEBRID REQUIRED</div><h2>Your sound. Your connection.</h2><label for="stream-quality">Streaming quality</label><select id="stream-quality"><option value="adaptive">Adaptive · connection-aware</option><option value="hires">Hi-res preferred · FLAC, CD fallback</option><option value="lossless">Lossless only · FLAC</option><option value="saver">Data Saver · AAC</option></select><p class="note">Adaptive chooses FLAC on a normal connection and AAC when Data Saver or a slow connection is detected. It may fall back to AAC if FLAC is unavailable. Applies to the next HiFi track; no mid-song switching or transcoding. Hi-res tries a direct hi-res FLAC file, then CD FLAC if unavailable or segmented. Segmented DASH and Atmos are not supported by this playback path. Fixed-format radio, open recordings and local files keep their original format.</p><label for="hifi-endpoint">HiFi service endpoint</label><input id="hifi-endpoint" type="url" placeholder="https://your-hifi-service.example" autocomplete="off"><p class="note">Use a working HiFi API service you have access to. It needs its own Tidal playback account and browser CORS support. No AllDebrid key is sent. Monochrome’s official endpoint is restricted to its own sites.</p><p id="stream-config-status" role="status"></p><button id="test-hifi">Check service</button><button id="save-stream-settings" class="primary">Save streaming options</button><p class="note">No endpoint? Radio and Open collection offer public FLAC sources without an account. Commercial catalog albums need an available playback service.</p>`);$('#stream-quality').value=mode;$('#hifi-endpoint').value=endpoint;$('#test-hifi').onclick=async()=>{const button=$('#test-hifi'),out=$('#stream-config-status');button.disabled=true;out.textContent='Checking service…';try{const base=$('#hifi-endpoint').value.trim();const u=safeURL(base);if(u.search||u.hash)throw Error('Use a base URL without a query or fragment.');const result=await get('',{},new AbortController().signal,base);out.textContent=result.version?'HiFi API '+String(result.version).slice(0,20)+' reachable. Playback account and audio availability are checked when you play.':'Server reachable, but it did not identify itself as HiFi.'}catch(e){out.textContent=e.message||'Service unreachable. Check HTTPS and browser CORS access.'}finally{button.disabled=false}};$('#save-stream-settings').onclick=()=>{try{const value=$('#hifi-endpoint').value.trim();if(value){const u=safeURL(value);if(u.search||u.hash)throw Error('Use the service base URL without a query or fragment.')}endpoint=value;mode=$('#stream-quality').value;try{localStorage.setItem('oktawka-stream-quality',mode);localStorage.setItem('oktawka-hifi',endpoint)}catch{}$('#stream-config-status').textContent='Saved. Applies to the next track. Endpoint availability is checked when you play.'}catch(e){$('#stream-config-status').textContent=e.message}}}
window.OktawkaStreaming={resolve,settings,status,qualities,match,manifest,get,queueURL,configured:()=>!!endpoint};$('#stream-settings').onclick=settings;const audioSettings=$('#audio-settings');if(audioSettings)audioSettings.onclick=settings;
})();
